namespace emon;

public static class Buftest {
    [Xunit.Fact]
    public static void TestPushAnswersTheNewLengthAndKeepsTheLowEightBits() {
        emon.Port.Buf b = emon.Port.NewBuf();
        emon.Testport.AssertEq(emon.Port.BufLen(b), 0, "empty");
        emon.Testport.AssertEq(emon.Port.BufPush(b, 65), 1, "the first push answers 1");
        emon.Testport.AssertEq(emon.Port.BufPush(b, 511), 2, "the second answers 2");
        emon.Testport.AssertEq(emon.Port.BufPush(b, -1), 3, "and the third 3");
        emon.Testport.AssertEq(emon.Port.BufPush(b, 128), 4, "a byte with the high bit");
        emon.Testport.AssertEq(emon.Port.BufPush(b, 4660), 5, "0x1234 keeps 0x34");
        emon.Testport.AssertEq(emon.Port.BufLen(b), 5, "five bytes");
        emon.Testport.AssertEq(emon.Port.BufAt(b, 0), 65, "0 is 65");
        emon.Testport.AssertEq(emon.Port.BufAt(b, 1), 255, "511 is 255");
        emon.Testport.AssertEq(emon.Port.BufAt(b, 2), 255, "-1 is 255");
        emon.Testport.AssertEq(emon.Port.BufAt(b, 3), 128, "128 reads back as 128, not -128");
        emon.Testport.AssertEq(emon.Port.BufAt(b, 4), 52, "0x34");
    }
    [Xunit.Fact]
    public static void TestSetOverwritesOneByte() {
        emon.Port.Buf b = emon.Port.NewBuf();
        emon.Port.BufPush(b, 1);
        emon.Port.BufPush(b, 2);
        emon.Port.BufPush(b, 3);
        emon.Port.BufSet(b, 1, 300);
        emon.Testport.AssertEq(emon.Port.BufAt(b, 0), 1, "untouched");
        emon.Testport.AssertEq(emon.Port.BufAt(b, 1), 44, "300 keeps 44");
        emon.Testport.AssertEq(emon.Port.BufAt(b, 2), 3, "untouched");
        emon.Testport.AssertEq(emon.Port.BufLen(b), 3, "the length did not change");
    }
    [Xunit.Fact]
    public static void TestTruncateGoesToALengthAndPushesResumeThere() {
        emon.Port.Buf b = emon.Port.NewBuf();
        emon.Port.BufPush(b, 10);
        emon.Port.BufPush(b, 20);
        emon.Port.BufPush(b, 30);
        emon.Port.BufTruncate(b, 1);
        emon.Testport.AssertEq(emon.Port.BufLen(b), 1, "one left");
        emon.Testport.AssertEq(emon.Port.BufPush(b, 99), 2, "the next push answers 2");
        emon.Testport.AssertEq(emon.Port.BufAt(b, 1), 99, "and lands at 1");
        emon.Port.BufTruncate(b, 0);
        emon.Testport.AssertEq(emon.Port.BufLen(b), 0, "emptied");
        emon.Port.BufTruncate(b, 0);
        emon.Testport.AssertEq(emon.Port.BufLen(b), 0, "emptying an empty one is allowed");
    }
    [Xunit.Fact]
    public static void TestAppendBlobCopiesASpan() {
        emon.Port.Buf b = emon.Port.NewBuf();
        emon.Port.BufPush(b, 7);
        emon.Port.BufAppendBlob(b, emon.Testport.HexBlob("00ff80aa55"), 1, 4);
        emon.Testport.AssertEq(emon.Port.BufLen(b), 4, "one and three");
        emon.Testport.AssertEq(emon.Port.BufAt(b, 0), 7, "the first byte");
        emon.Testport.AssertEq(emon.Port.BufAt(b, 1), 255, "ff");
        emon.Testport.AssertEq(emon.Port.BufAt(b, 2), 128, "80");
        emon.Testport.AssertEq(emon.Port.BufAt(b, 3), 170, "aa");
        emon.Port.BufAppendBlob(b, emon.Testport.HexBlob("0102"), 0, 0);
        emon.Testport.AssertEq(emon.Port.BufLen(b), 4, "an empty span appends nothing");
    }
    [Xunit.Fact]
    public static void TestItGrowsPastItsFirstAllocation() {
        emon.Port.Buf b = emon.Port.NewBuf();
        int i = 0;
        while (i < 100000) {
            emon.Port.BufPush(b, i);
            i += 1;
        }
        emon.Testport.AssertEq(emon.Port.BufLen(b), 100000, "100,000 bytes");
        emon.Testport.AssertEq(emon.Port.BufAt(b, 0), 0, "first");
        emon.Testport.AssertEq(emon.Port.BufAt(b, 255), 255, "255");
        emon.Testport.AssertEq(emon.Port.BufAt(b, 256), 0, "wraps: 256 is 0");
        emon.Testport.AssertEq(emon.Port.BufAt(b, 99999), 159, "99999 is 0x9F");
    }
    [Xunit.Fact]
    public static void TestBlobLendsTheContents() {
        emon.Port.Buf b = emon.Port.NewBuf();
        emon.Port.BufPush(b, 1);
        emon.Port.BufPush(b, 255);
        emon.Port.BufPush(b, 128);
        emon.Testport.AssertEq(emon.Port.BlobLen(emon.Port.BufBlob(b)), 3, "three bytes");
        emon.Testport.AssertEq(emon.Port.BlobU8(emon.Port.BufBlob(b), 0), 1, "1");
        emon.Testport.AssertEq(emon.Port.BlobU8(emon.Port.BufBlob(b), 1), 255, "255");
        emon.Testport.AssertEq(emon.Port.BlobU8(emon.Port.BufBlob(b), 2), 128, "128");
        emon.Port.BufPush(b, 5);
        emon.Testport.AssertEq(emon.Port.BlobLen(emon.Port.BufBlob(b)), 4, "a borrow taken after a write sees it");
    }
}
